BEGIN;
DELETE FROM questions WHERE topic = 'Electrochemistry' AND subtopic IN ('Galvanic Cell Components', 'Standard Reduction Potentials', 'Cell Potential & EMF');

-- Q1 [Galvanic Cell Components · easy · Skill 1 · 4C Electrochemistry (GC) · ans B] (g26)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Galvanic Cell Components',
    $qt26$A galvanic cell is constructed with a zinc electrode in \(\text{Zn(NO}_3)_2\) solution and a copper electrode in \(\text{Cu(NO}_3)_2\) solution, with the two half-cells connected externally by a wire and internally by a salt bridge filled with \(\text{KNO}_3\). As the cell discharges, what is the primary function of the salt bridge?$qt26$,
    $op26$[{"label":"A","text":"It carries electrons from the zinc electrode to the copper electrode, completing the external circuit"},{"label":"B","text":"It maintains electrical neutrality in each half-cell by allowing ion migration, completing the internal circuit"},{"label":"C","text":"It transfers dissolved \\(\\text{Zn}^{2+}\\) ions directly onto the copper electrode so they can be reduced"},{"label":"D","text":"It generates the cell's voltage by establishing the difference in reduction potential between the two electrodes"}]$op26$::jsonb,
    'B',
    $ex26$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is B because the salt bridge's primary job is to maintain charge neutrality in each half-cell and thereby complete the internal portion of the circuit. As the cell discharges, \(\text{Zn}\) is oxidized at the anode (\(\text{Zn} \rightarrow \text{Zn}^{2+} + 2e^-\)), which would leave the anode compartment with excess positive charge, while \(\text{Cu}^{2+}\) is reduced at the cathode (\(\text{Cu}^{2+} + 2e^- \rightarrow \text{Cu}\)), which would leave the cathode compartment with excess negative charge. The \(\text{KNO}_3\) salt bridge counteracts this buildup: \(\text{NO}_3^-\) anions migrate toward the anode and \(\text{K}^+\) cations migrate toward the cathode, keeping each solution neutral and allowing current to keep flowing. Without it, charge would accumulate, no further electron flow would occur, and the cell would stop. (Choice A) Electrons travel through the external metal wire, not the salt bridge; this choice confuses the internal ionic pathway with the external electronic pathway. (Choice C) The salt bridge does not deliver \(\text{Zn}^{2+}\) to the copper electrode; \(\text{Cu}^{2+}\) already in the cathode solution is what is reduced onto the copper, so this describes a process that does not occur. (Choice D) The cell voltage arises from the intrinsic difference in reduction potentials of the two electrode half-reactions, an inherent thermodynamic property, not something the salt bridge produces. Skill 1$ex26$,
    'easy', '4C', $cc26$Electrochemistry (GC)$cc26$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a26A$salt bridge conducts electrons instead of ions$a26A$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a26C$salt bridge physically transports the oxidized metal ion to the other electrode$a26C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a26D$attributes the source of EMF (potential difference) to the salt bridge$a26D$ FROM q;

-- Q2 [Galvanic Cell Components · easy · Skill 1 · 4C Electrochemistry (GC) · ans C] (g27)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Galvanic Cell Components',
    $qt27$A galvanic cell is built by connecting a tin electrode immersed in \(\text{Sn}^{2+}\) solution to a silver electrode immersed in \(\text{Ag}^{+}\) solution. The two electrodes are joined externally by a metal wire that runs through a voltmeter, and the two solutions are connected internally by a salt bridge. With the salt bridge already handling the internal ion flow, what is the role of the voltmeter in this cell?$qt27$,
    $op27$[{"label":"A","text":"It supplies the electrical energy that drives the cell reaction forward."},{"label":"B","text":"It completes the internal circuit by letting ions migrate between the two compartments."},{"label":"C","text":"It measures the cell's electromotive force (EMF) — the electrical potential difference between the two half-cells."},{"label":"D","text":"It is the electrode surface at which reduction takes place."}]$op27$::jsonb,
    'C',
    $ex27$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is C because the voltmeter is the instrument wired into the external circuit to read voltage: it registers the cell's electromotive force (EMF), the electrical potential difference between the two half-cells that arises from their different tendencies to be reduced. In this cell that difference reflects the gap between the \(\text{Ag}^{+}/\text{Ag}\) and \(\text{Sn}^{2+}/\text{Sn}\) reduction potentials, and the voltmeter simply reports that potential difference without itself participating in the chemistry. (Choice A) A galvanic cell is spontaneous and generates its own electrical energy, so no external source is needed to drive it; an energy-supplying power source belongs to an electrolytic cell, not to the voltmeter of a galvanic cell. (Choice B) Completing the internal circuit by permitting ion migration between compartments is the function of the salt bridge, which is the separate component already linking the two solutions, not the voltmeter in the external wire. (Choice D) The electrode surface at which reduction occurs is the cathode (here the silver electrode), which is part of a half-cell, whereas the voltmeter is an instrument placed in the external circuit and is not an electrode. Skill 1$ex27$,
    'easy', '4C', $cc27$Electrochemistry (GC)$cc27$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a27A$confusing a galvanic cell's self-generated voltage with an externally supplied driving energy$a27A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a27B$attributing the salt bridge's internal-circuit-completing role to the voltmeter$a27B$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a27D$mistaking the measuring instrument for the cathode electrode where reduction occurs$a27D$ FROM q;

-- Q3 [Galvanic Cell Components · medium · Skill 2 · 4C Electrochemistry (GC) · ans D] (g28)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Galvanic Cell Components',
    $qt28$A galvanic cell is constructed with a nickel electrode immersed in \(1\ \text{M}\ \text{Ni(NO}_3)_2\) and a silver electrode immersed in \(1\ \text{M}\ \text{AgNO}_3\). The two half-cells are joined by a salt bridge containing \(\text{NaNO}_3\). During spontaneous operation, the nickel electrode is oxidized (\(\text{Ni} \rightarrow \text{Ni}^{2+} + 2e^-\)) while silver ions are reduced at the silver electrode (\(\text{Ag}^+ + e^- \rightarrow \text{Ag}\)). Which statement most accurately describes how ions from the salt bridge move, and why?$qt28$,
    $op28$[{"label":"A","text":"\\(\\text{NO}_3^-\\) ions migrate into the nickel compartment because the nickel electrode is the positive terminal that attracts anions."},{"label":"B","text":"\\(\\text{Na}^+\\) ions migrate into the nickel compartment to balance the positive charge of the \\(\\text{Ni}^{2+}\\) ions being generated there."},{"label":"C","text":"\\(\\text{NO}_3^-\\) ions migrate into the silver compartment to balance the positive charge of the \\(\\text{Ni}^{2+}\\) ions being generated there."},{"label":"D","text":"\\(\\text{NO}_3^-\\) ions migrate into the nickel compartment to balance the positive charge of the \\(\\text{Ni}^{2+}\\) ions being generated there."}]$op28$::jsonb,
    'D',
    $ex28$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is D because the salt bridge exists to maintain electrical neutrality in each half-cell, and electrical neutrality demands that negative ions (anions) move toward the compartment that is accumulating positive charge. As the nickel electrode is oxidized, \(\text{Ni} \rightarrow \text{Ni}^{2+} + 2e^-\), each dissolving nickel atom releases a \(\text{Ni}^{2+}\) cation into the anode (nickel) compartment while its electrons leave through the external wire; the solution there would steadily build up excess positive charge. To counter this, \(\text{NO}_3^-\) anions from the \(\text{NaNO}_3\) salt bridge migrate into the nickel compartment, supplying negative charge that exactly balances the newly formed \(\text{Ni}^{2+}\) cations. (Simultaneously \(\text{Na}^+\) cations move into the silver compartment, where \(\text{Ag}^+\) is being consumed and \(\text{NO}_3^-\) is left in excess, but the question asks about the anode side.) The general rule is that anions always migrate toward the anode compartment and cations toward the cathode compartment, regardless of cell type. (Choice A) reaches the right destination by faulty reasoning: in a galvanic cell the anode (nickel) is the negative terminal, not the positive one, so anions are not drawn there by electrode polarity; they migrate there to neutralize the dissolved \(\text{Ni}^{2+}\) cations accumulating in solution. (Choice B) reverses the species: it is anions, not cations, that move toward the compartment gaining positive charge, so \(\text{Na}^+\) moving into the nickel compartment would worsen the positive-charge buildup rather than neutralize it; \(\text{Na}^+\) instead migrates toward the silver (cathode) compartment. (Choice C) identifies the correct migrating ion (\(\text{NO}_3^-\)) and the correct driving cause (balancing \(\text{Ni}^{2+}\)) but sends it to the wrong compartment; the \(\text{Ni}^{2+}\) is generated in the nickel compartment, so that is where the \(\text{NO}_3^-\) must go, not into the silver compartment. Skill 2$ex28$,
    'medium', '4C', $cc28$Electrochemistry (GC)$cc28$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a28A$Right destination via wrong mechanism: claims the galvanic anode is the positive terminal attracting anions, mislabeling electrode polarity$a28A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a28B$Sends the cation (Na+) toward the positively charging anode compartment, reversing the anion-toward-anode rule$a28B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a28C$Correct migrating ion and cause but routes the anion to the cathode compartment instead of the anode compartment where Ni2+ forms$a28C$ FROM q;

-- Q4 [Galvanic Cell Components · medium · Skill 2 · 4C Electrochemistry (GC) · ans A] (g29)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Galvanic Cell Components',
    $qt29$A galvanic cell is constructed by placing a zinc electrode in a beaker of \(\text{Zn}^{2+}(aq)\) and a copper electrode in a separate beaker of \(\text{Cu}^{2+}(aq)\), with the two beakers joined by an external wire (through a small motor) and a salt bridge. The overall spontaneous reaction is \(\text{Zn}(s) + \text{Cu}^{2+}(aq) \rightarrow \text{Zn}^{2+}(aq) + \text{Cu}(s)\). A student asks why the two half-cells are kept in separate compartments instead of simply pouring both solutions and both metal strips into a single beaker, given that the same overall redox reaction would still occur. Which statement best explains the consequence of keeping the half-cells separated?$qt29$,
    $op29$[{"label":"A","text":"Separating the half-cells forces the transferred electrons to travel through the external wire, so the cell can deliver usable electrical work; if the solutions were mixed in one container, electrons would pass directly from the zinc to the \\(\\text{Cu}^{2+}\\) ions at the metal surface and the energy would be released as heat instead of as current."},{"label":"B","text":"Mixing both metals and both solutions in a single container would increase the cell's current output, because the reducing and oxidizing species could collide more frequently and transfer charge faster than when forced through a narrow wire."},{"label":"C","text":"Separating the half-cells exists only so that the salt bridge has somewhere to sit; the two compartments are not chemically necessary, and removing the salt bridge while keeping one mixed beaker would let the cell run identically."},{"label":"D","text":"Separating the half-cells is required only to prevent an insoluble \\(\\text{ZnCu}\\) precipitate from forming; otherwise the two solutions could be combined with no effect on the electrical output."}]$op29$::jsonb,
    'A',
    $ex29$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is A because the entire purpose of a galvanic cell is to capture the energy of a spontaneous redox reaction as electrical work rather than as heat. By placing the reducing agent (\(\text{Zn}\)) and the oxidizing agent (\(\text{Cu}^{2+}\)) in physically separate compartments, the only path electrons can take from the zinc to the \(\text{Cu}^{2+}\) ions is through the external wire connecting the two electrodes; that controlled flow of electrons through the wire is the usable current that can power a motor or light bulb. If instead both metal strips and both solutions were combined in one beaker, the \(\text{Cu}^{2+}\) ions would contact the zinc surface directly, electrons would hop straight from the zinc atoms to the \(\text{Cu}^{2+}\) ions at that surface, and copper would plate directly onto the zinc. The reaction would still be spontaneous, but the energy would be dissipated as heat with no electrons routed through the wire, so no electrical work could be harvested. (Choice B) is incorrect because mixing does not increase usable current; in fact it eliminates the externally routed current entirely, since direct electron transfer at the metal surface bypasses the wire and releases the energy as heat. (Choice C) is incorrect because the separation is chemically essential, not merely a place to put the salt bridge: without two compartments there is no external electron path, and a single mixed beaker would simply undergo a direct redox reaction regardless of any salt bridge. (Choice D) is incorrect because no "\(\text{ZnCu}\)" precipitate forms; the reason for separation is to route electrons through the wire for usable work, not to avoid a precipitate. Skill 2$ex29$,
    'medium', '4C', $cc29$Electrochemistry (GC)$cc29$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a29B$Believes direct contact between reactants increases harvestable current rather than eliminating the external electron path$a29B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a29C$Correctly notes the salt bridge is involved but wrongly concludes the two-compartment separation is not chemically necessary for routing electrons$a29C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a29D$Invents a precipitation rationale (avoiding an insoluble product) as the reason for separation instead of the electron-routing rationale$a29D$ FROM q;

-- Q5 [Galvanic Cell Components · medium · Skill 2 · 4C Electrochemistry (GC) · ans B] (g30)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Galvanic Cell Components',
    $qt30$A galvanic cell is built by connecting a cadmium electrode immersed in aqueous \(\text{CdSO}_4\) to a tin electrode immersed in aqueous \(\text{SnSO}_4\). The two electrodes are joined by a metal wire through an external voltmeter, and the two solutions are connected by a salt bridge containing \(\text{KNO}_3\). The relevant standard reduction potentials are \(\text{Cd}^{2+} + 2e^- \rightarrow \text{Cd}(s),\ E^{\circ} = -0.40\ \text{V}\) and \(\text{Sn}^{2+} + 2e^- \rightarrow \text{Sn}(s),\ E^{\circ} = -0.14\ \text{V}\). As the cell operates spontaneously, which species supplies the cations that are reduced and deposited as neutral metal onto an electrode, and how does that supply reach the electrode surface?$qt30$,
    $op30$[{"label":"A","text":"The dissolved \\(\\text{Cd}^{2+}\\) ions already present in the \\(\\text{CdSO}_4\\) electrolyte are reduced and plated onto the cadmium electrode, reaching it by migrating through the solution."},{"label":"B","text":"The dissolved \\(\\text{Sn}^{2+}\\) ions already present in the \\(\\text{SnSO}_4\\) electrolyte are reduced and plated onto the tin electrode, reaching it by migrating through the solution."},{"label":"C","text":"Metal cations travel from the cadmium half-cell through the salt bridge to the tin electrode, where they are reduced and plated out."},{"label":"D","text":"Electrons delivered through the external wire combine with \\(\\text{Sn}^{2+}\\) generated in solution by the wire, plating tin onto the tin electrode."}]$op30$::jsonb,
    'B',
    $ex30$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is B because the half-cell where reduction (plating of neutral metal) occurs is the cathode, and the cathode is the electrode with the more positive standard reduction potential. Comparing \(E^{\circ}(\text{Sn}^{2+}/\text{Sn}) = -0.14\ \text{V}\) with \(E^{\circ}(\text{Cd}^{2+}/\text{Cd}) = -0.40\ \text{V}\), tin is more positive, so the tin electrode is the cathode and reduction occurs there: \(\text{Sn}^{2+} + 2e^- \rightarrow \text{Sn}(s)\). The cations that are reduced are the \(\text{Sn}^{2+}\) ions already dissolved in the \(\text{SnSO}_4\) electrolyte of that same half-cell; the aqueous electrolyte is the reservoir of mobile metal cations, and those ions reach the electrode by migrating through the solution toward the negatively-charging surface and depositing on it. (Note that meanwhile the cadmium electrode is the anode, where \(\text{Cd}(s) \rightarrow \text{Cd}^{2+} + 2e^-\), confirming \(E^{\circ}_{\text{cell}} = -0.14 - (-0.40) = +0.26\ \text{V} > 0\), a spontaneous galvanic process.) (Choice A) This correctly identifies that the electrolyte supplies the plated cations, but it places the plating in the wrong half-cell: \(\text{Cd}^{2+}\) is not reduced because the cadmium electrode is the anode (oxidation), where cadmium metal dissolves into the solution rather than plating out. (Choice C) The salt bridge carries ions only to preserve electroneutrality (anions such as \(\text{NO}_3^-\) move toward the anode compartment and \(\text{K}^+\) toward the cathode compartment); it is not the route by which the depositing metal cation is delivered, and the depositing \(\text{Sn}^{2+}\) originates in its own half-cell electrolyte, not from the cadmium side. (Choice D) The external wire conducts electrons, not ions, and it cannot generate \(\text{Sn}^{2+}\) in solution; the \(\text{Sn}^{2+}\) being reduced is supplied by the dissolved \(\text{SnSO}_4\), so this choice misattributes the source of the cations to the wire. Skill 2$ex30$,
    'medium', '4C', $cc30$Electrochemistry (GC)$cc30$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a30A$right role for electrolyte but plating assigned to the anode half-cell$a30A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a30C$believes the salt bridge transports the depositing metal cation between half-cells$a30C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a30D$thinks the external wire carries/creates ions rather than conducting electrons only$a30D$ FROM q;

-- Q6 [Galvanic Cell Components · medium · Skill 2 · 4C Electrochemistry (GC) · ans C] (g31)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Galvanic Cell Components',
    $qt31$A galvanic cell is constructed with an iron electrode immersed in \(\text{FeSO}_4(aq)\) and a copper electrode immersed in \(\text{CuSO}_4(aq)\), with the two half-cells joined by a salt bridge containing \(\text{KCl}\). As the cell operates spontaneously, in which direction do the \(\text{K}^{+}\) ions of the salt bridge migrate, and what is the underlying reason?$qt31$,
    $op31$[{"label":"A","text":"Into the copper half-cell, because the copper electrode is the anode and attracts cations as it is oxidized."},{"label":"B","text":"Into the iron half-cell, because \\(\\text{Fe}\\) is oxidized to \\(\\text{Fe}^{2+}\\), adding positive charge that the \\(\\text{K}^{+}\\) ions reinforce."},{"label":"C","text":"Into the copper half-cell, because \\(\\text{Cu}^{2+}\\) ions are being reduced and removed from solution, leaving excess \\(\\text{SO}_4^{2-}\\) that would make the compartment negative."},{"label":"D","text":"Into the iron half-cell, because the salt bridge always sends cations toward the electrode where oxidation occurs."}]$op31$::jsonb,
    'C',
    $ex31$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is C because in this galvanic cell iron is the more easily oxidized metal and serves as the anode (\(\text{Fe} \rightarrow \text{Fe}^{2+} + 2e^-\)), while copper serves as the cathode (\(\text{Cu}^{2+} + 2e^- \rightarrow \text{Cu}(s)\)). At the cathode, \(\text{Cu}^{2+}\) cations are continuously consumed (reduced and deposited as metallic copper), which removes positive charge from the copper compartment and leaves behind an excess of the spectator \(\text{SO}_4^{2-}\) anions. That compartment would therefore accumulate net negative charge and stall the reaction. To preserve electroneutrality, salt-bridge cations (\(\text{K}^{+}\)) migrate into the cathode (copper) compartment, replacing the positive charge lost as \(\text{Cu}^{2+}\) is reduced; meanwhile the salt-bridge anions (\(\text{Cl}^{-}\)) migrate toward the anode (iron) compartment, where \(\text{Fe}^{2+}\) is being added. In any electrochemical cell, cations of the salt bridge move toward the cathode, the electrode at which reduction occurs. (Choice A) The copper electrode is the cathode (site of reduction), not the anode; the directional claim happens to point to the correct half-cell but the rationale misidentifies the electrode and the process occurring there. (Choice B) This reverses the cell roles: although Fe is indeed oxidized to \(\text{Fe}^{2+}\), that compartment is gaining positive charge, so additional \(\text{K}^{+}\) would worsen the imbalance rather than correct it; it is the anions (\(\text{Cl}^{-}\)), not cations, that move toward the iron half-cell. (Choice D) This states a reversed rule: salt-bridge cations migrate toward the cathode (reduction site), not toward the anode (oxidation site), so both the direction and the stated principle are incorrect. Skill 2$ex31$,
    'medium', '4C', $cc31$Electrochemistry (GC)$cc31$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a31A$Right compartment, wrong electrode identity and process (labels copper as anode/oxidation)$a31A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a31B$Sends cations to the anode compartment, treating added Fe2+ charge as something cations should reinforce$a31B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a31D$Believes salt-bridge cations always travel toward the oxidation (anode) electrode$a31D$ FROM q;

-- Q7 [Galvanic Cell Components · hard · Skill 2 · 4C Electrochemistry (GC) · ans D] (g32)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Galvanic Cell Components',
    $qt32$A galvanic cell is built from an aluminum electrode immersed in \(1\ \text{M}\ \text{Al(NO}_3)_3\) and a copper electrode immersed in \(1\ \text{M}\ \text{Cu(NO}_3)_2\), with the two half-cells connected by an external wire and a salt bridge containing \(\text{KBr}\). The relevant standard reduction potentials are \(\text{Al}^{3+} + 3e^- \rightarrow \text{Al}(s),\ E^{\circ} = -1.66\ \text{V}\) and \(\text{Cu}^{2+} + 2e^- \rightarrow \text{Cu}(s),\ E^{\circ} = +0.34\ \text{V}\). As the cell runs, a technician measures a steadily growing net positive charge in the solution surrounding the aluminum electrode. Which choice most likely identifies the salt-bridge ion that migrates into the aluminum compartment to counteract this charge buildup, together with the correct consequence of clamping the salt bridge shut?$qt32$,
    $op32$[{"label":"A","text":"\\(\\text{NO}_3^-\\) from the copper compartment migrates through the bridge into the aluminum compartment; clamping the bridge shut halts the cell because charge can no longer be balanced and current ceases."},{"label":"B","text":"\\(\\text{K}^+\\) migrates into the aluminum compartment; clamping the bridge shut halts the cell because charge can no longer be balanced and current ceases."},{"label":"C","text":"\\(\\text{Br}^-\\) migrates into the aluminum compartment; clamping the bridge shut has no effect because the external wire still completes the circuit and current continues."},{"label":"D","text":"\\(\\text{Br}^-\\) migrates into the aluminum compartment; clamping the bridge shut halts the cell because charge can no longer be balanced and current ceases."}]$op32$::jsonb,
    'D',
    $ex32$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is D because the observation pins down the anode, the anode's half-reaction dictates which sign of charge accumulates, and the salt-bridge ion that neutralizes it must be the bridge anion, after which the role of the bridge in completing the circuit determines what happens when it is blocked. First, rank the electrodes: \(\text{Cu}^{2+}\) has the more positive reduction potential (\(+0.34\ \text{V}\) versus \(-1.66\ \text{V}\)), so copper is reduced at the cathode and aluminum is oxidized at the anode, giving \(E^{\circ}_{\text{cell}} = E^{\circ}_{\text{red,cathode}} - E^{\circ}_{\text{red,anode}} = (+0.34) - (-1.66) = +2.00\ \text{V} > 0\), a spontaneous galvanic cell. The aluminum compartment is therefore the anode, where \(\text{Al}(s) \rightarrow \text{Al}^{3+} + 3e^-\) injects \(\text{Al}^{3+}\) cations into solution; this is precisely the source of the growing net positive charge the technician measures. To preserve electroneutrality, negative charge must flow into that compartment, which means a salt-bridge anion must migrate in. The \(\text{KBr}\) bridge supplies \(\text{K}^+\) and \(\text{Br}^-\); the anion \(\text{Br}^-\) is the species that migrates toward the anode to cancel the \(\text{Al}^{3+}\) buildup (while \(\text{K}^+\) migrates the other way, into the cathode compartment where \(\text{Cu}^{2+}\) is being consumed). Finally, the salt bridge is the only ionic path that closes the circuit: if it is clamped shut, the anode solution becomes ever more positive and the cathode solution ever more negative, this charge separation opposes further electron flow, and current ceases almost immediately. (Choice A) \(\text{NO}_3^-\) is the spectator anion already present in each half-cell solution, not an ion supplied by the \(\text{KBr}\) salt bridge; the question asks specifically which salt-bridge ion migrates in, and the bridge delivers \(\text{Br}^-\), not nitrate, into the anode compartment. The consequence stated is correct, but the migrating bridge ion is misidentified. (Choice B) \(\text{K}^+\) is the bridge cation; cations migrate toward the cathode, not toward the anode, so sending \(\text{K}^+\) into the already-positive aluminum compartment would worsen the imbalance rather than counteract it. This choice reverses the direction in which each bridge ion travels even though it correctly notes that blocking the bridge stops the cell. (Choice C) \(\text{Br}^-\) is correctly identified as the ion entering the aluminum compartment, but the claim that current continues with the bridge clamped is wrong: an electrochemical cell needs both an electronic path (the wire) and an ionic path (the bridge) to operate, and removing the ionic path lets charge accumulate until it stalls electron flow. Skill 2$ex32$,
    'hard', '4C', $cc32$Electrochemistry (GC)$cc32$, 'general-chemistry', 2, 160
  ) RETURNING id
)
