UNION ALL SELECT id, 'C', 'reversed_relationship', $a42C$imagines the fixed potential is diluted or spread thinner across a larger cell volume$a42C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a42D$correctly senses the cell was rebuilt but wrongly concludes the potential must be recomputed for the new geometry$a42D$ FROM q;

-- Q18 [Cell Potential & EMF · medium · Skill 2 · 4C Electrochemistry (GC) · ans C] (g43)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Potential & EMF',
    $qt43$A student proposes building a galvanic (voltaic) cell based on the reaction \(\text{Fe(s)} + \text{Ni}^{2+}(aq) \rightarrow \text{Fe}^{2+}(aq) + \text{Ni(s)}\), claiming that iron metal will spontaneously reduce nickel(II) ions under standard conditions. The relevant standard reduction potentials are \(\text{Ni}^{2+} + 2e^{-} \rightarrow \text{Ni(s)},\ E^{\circ}_{\text{red}} = -0.25\ \text{V}\) and \(\text{Fe}^{2+} + 2e^{-} \rightarrow \text{Fe(s)},\ E^{\circ}_{\text{red}} = -0.44\ \text{V}\). Based on the sign of \(E^{\circ}_{\text{cell}}\), which statement correctly evaluates the proposal?$qt43$,
    $op43$[{"label":"A","text":"The reaction is spontaneous because \\(E^{\\circ}_{\\text{cell}} = +0.69\\ \\text{V}\\), so \\(\\Delta G^{\\circ} < 0\\)."},{"label":"B","text":"The reaction is nonspontaneous because \\(E^{\\circ}_{\\text{cell}} = -0.19\\ \\text{V}\\), so \\(\\Delta G^{\\circ} > 0\\)."},{"label":"C","text":"The reaction is spontaneous because \\(E^{\\circ}_{\\text{cell}} = +0.19\\ \\text{V}\\), so \\(\\Delta G^{\\circ} < 0\\)."},{"label":"D","text":"The reaction is nonspontaneous because \\(E^{\\circ}_{\\text{cell}} = -0.69\\ \\text{V}\\), so \\(\\Delta G^{\\circ} > 0\\)."}]$op43$::jsonb,
    'C',
    $ex43$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is C because in the proposed reaction \(\text{Fe(s)} + \text{Ni}^{2+} \rightarrow \text{Fe}^{2+} + \text{Ni(s)}\), \(\text{Ni}^{2+}\) gains electrons (reduction, so the \(\text{Ni}^{2+}/\text{Ni}\) couple is the cathode) and \(\text{Fe(s)}\) loses electrons (oxidation, so the \(\text{Fe}^{2+}/\text{Fe}\) couple is the anode). Applying \(E^{\circ}_{\text{cell}} = E^{\circ}_{\text{red,cathode}} - E^{\circ}_{\text{red,anode}} = (-0.25\ \text{V}) - (-0.44\ \text{V}) = +0.19\ \text{V}\). Note that both standard potentials are used as tabulated reduction values and only subtracted; the anode's sign is not separately flipped. Because \(E^{\circ}_{\text{cell}} = +0.19\ \text{V} > 0\), \(\Delta G^{\circ} = -nFE^{\circ}_{\text{cell}} < 0\), so the reaction is spontaneous as written and the proposal is correct. (Choice A) This adds the magnitudes of the two potentials \((0.44 + 0.25 = 0.69\ \text{V})\) instead of subtracting the signed reduction potentials, an error from flipping the anode sign and then also subtracting. (Choice B) This reverses the conclusion by misassigning the cathode and anode (treating \(\text{Fe}^{2+}/\text{Fe}\) as the reduction half), giving \((-0.44) - (-0.25) = -0.19\ \text{V}\); this is the cell potential for the reverse reaction, not the proposed one. (Choice D) This both flips the anode sign incorrectly (yielding 0.69 V) and reverses the spontaneity sign, compounding two errors. Skill 2$ex43$,
    'medium', '4C', $cc43$Electrochemistry (GC)$cc43$, 'general-chemistry', 2, 110
  ) RETURNING id
)
