-- Q19 [Cell Potential & EMF · medium · Skill 2 · 4C Electrochemistry (GC) · ans D] (g44)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Potential & EMF',
    $qt44$A galvanic cell is constructed under standard conditions, and its standard cell potential is measured to be \(E^{\circ}_{\text{cell}} = +1.10\ \text{V}\). At the cathode, the reduction half-reaction is \(\text{Ag}^{+} + e^{-} \rightarrow \text{Ag}\), which has a standard reduction potential of \(E^{\circ}_{\text{red}} = +0.80\ \text{V}\). The other electrode serves as the anode. What is the standard reduction potential, \(E^{\circ}_{\text{red}}\), of the anode half-cell couple?$qt44$,
    $op44$[{"label":"A","text":"\\(-1.90\\ \\text{V}\\)"},{"label":"B","text":"\\(+0.30\\ \\text{V}\\)"},{"label":"C","text":"\\(+1.90\\ \\text{V}\\)"},{"label":"D","text":"\\(-0.30\\ \\text{V}\\)"}]$op44$::jsonb,
    'D',
    $ex44$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is D because the standard cell potential relates the two half-cell reduction potentials through \(E^{\circ}_{\text{cell}} = E^{\circ}_{\text{red,cathode}} - E^{\circ}_{\text{red,anode}}\). Both potentials are tabulated as reduction potentials, and you subtract the anode's reduction potential from the cathode's; you do NOT also flip the sign of the anode value. Substituting the known quantities, \(+1.10\ \text{V} = (+0.80\ \text{V}) - E^{\circ}_{\text{red,anode}}\). Solving, \(E^{\circ}_{\text{red,anode}} = +0.80\ \text{V} - 1.10\ \text{V} = -0.30\ \text{V}\). A negative anode reduction potential is consistent with a spontaneous galvanic cell (\(E^{\circ}_{\text{cell}} > 0\)): the anode couple is more easily oxidized (less easily reduced) than the silver couple, so it correctly loses electrons. (Choice A) \(-1.90\ \text{V}\) arises from incorrectly flipping the sign of the cathode potential before combining (e.g., \(-0.80 - 1.10\)), an extra and unwarranted sign change layered onto the subtraction. (Choice B) \(+0.30\ \text{V}\) is the magnitude of the correct value with the wrong sign; it results from solving \(E^{\circ}_{\text{red,anode}} = 1.10\ \text{V} - 0.80\ \text{V}\), which reverses the subtraction and yields a positive number rather than \(+0.80 - 1.10\). (Choice C) \(+1.90\ \text{V}\) comes from adding the two potentials (\(0.80 + 1.10\)) instead of subtracting, which misapplies the relationship between cell potential and half-cell potentials. Skill 2$ex44$,
    'medium', '4C', $cc44$Electrochemistry (GC)$cc44$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a44A$Applies an extra unwarranted sign flip to the cathode potential before combining$a44A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a44B$Correct magnitude but wrong sign from reversing the subtraction order$a44B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a44C$Adds the two potentials instead of subtracting cathode minus anode$a44C$ FROM q;

-- Q20 [Standard Reduction Potentials · easy · Skill 1 · 4C Electrochemistry (GC) · ans C] (g87)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Standard Reduction Potentials',
    $qt87$A student is given the following two standard reduction half-reactions at 298 K: \(\text{Zn}^{2+} + 2e^- \rightarrow \text{Zn}\quad E^{\circ}_{\text{red}} = -0.76\ \text{V}\) \(\text{Cu}^{2+} + 2e^- \rightarrow \text{Cu}\quad E^{\circ}_{\text{red}} = +0.34\ \text{V}\) Based on these standard reduction potentials, which species is the stronger oxidizing agent?$qt87$,
    $op87$[{"label":"A","text":"\\(\\text{Zn}\\) metal"},{"label":"B","text":"\\(\\text{Zn}^{2+}\\)"},{"label":"C","text":"\\(\\text{Cu}^{2+}\\)"},{"label":"D","text":"\\(\\text{Cu}\\) metal"}]$op87$::jsonb,
    'C',
    $ex87$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is C because the standard reduction potential measures the tendency of a species to be reduced (to gain electrons), and an oxidizing agent is the species that gets reduced. The more positive the \(E^{\circ}_{\text{red}}\), the greater the pull on electrons and therefore the stronger the oxidizing agent. Comparing the two cations that can be reduced, \(\text{Cu}^{2+}\) has \(E^{\circ}_{\text{red}} = +0.34\ \text{V}\) while \(\text{Zn}^{2+}\) has \(E^{\circ}_{\text{red}} = -0.76\ \text{V}\). Because \(+0.34\ \text{V} > -0.76\ \text{V}\), \(\text{Cu}^{2+}\) is more readily reduced and is the stronger oxidizing agent. (Choice A) \(\text{Zn}\) metal is the species most easily oxidized in this pair, which makes it the strongest reducing agent, not an oxidizing agent; this choice confuses the role of reducing agent with that of oxidizing agent. (Choice B) \(\text{Zn}^{2+}\) is the weaker oxidizing agent, not the stronger one; its more negative \(E^{\circ}_{\text{red}}\) means it resists reduction, so selecting it reverses the rule that a more positive potential indicates a stronger oxidizer. (Choice D) \(\text{Cu}\) metal is the reduced (product) form of the copper couple and acts as a reducing agent; while it comes from the couple with the more positive potential, the oxidizing agent is the cation \(\text{Cu}^{2+}\) that gains electrons, not the neutral metal. Skill 1$ex87$,
    'easy', '4C', $cc87$Electrochemistry (GC)$cc87$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a87A$Confuses oxidizing agent with reducing agent (selects the easily oxidized Zn metal)$a87A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a87B$Picks the more negative E°red as the stronger oxidizer, inverting the rule$a87B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a87D$Right couple, wrong member: picks the neutral Cu metal instead of the Cu2+ cation that is reduced$a87D$ FROM q;

-- Q21 [Standard Reduction Potentials · hard · Skill 2 · 4C Electrochemistry (GC) · ans D] (g88)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Standard Reduction Potentials',
    $qt88$A chemist has access to three metal/metal-ion couples and their standard reduction potentials at 298 K: \(\text{Fe}^{2+} + 2e^- \rightarrow \text{Fe}(s)\), \(E^{\circ} = -0.44\ \text{V}\); \(\text{Ni}^{2+} + 2e^- \rightarrow \text{Ni}(s)\), \(E^{\circ} = -0.25\ \text{V}\); and \(\text{Ag}^{+} + e^- \rightarrow \text{Ag}(s)\), \(E^{\circ} = +0.80\ \text{V}\). She wants to (i) rank the three solid metals from strongest to weakest reducing agent and (ii) build, from exactly two of these couples, the single galvanic cell that delivers a positive standard cell potential by oxidizing the metal that is the strongest reducing agent. Which statement correctly pairs the reducing-strength ranking with the appropriate galvanic cell?$qt88$,
    $op88$[{"label":"A","text":"Reducing strength \\(\\text{Fe} > \\text{Ni} > \\text{Ag}\\); the cell with \\(\\text{Fe}(s)\\) as the anode and \\(\\text{Ag}^{+}/\\text{Ag}\\) as the cathode gives \\(E^{\\circ}_{\\text{cell}} = +0.36\\ \\text{V}\\)."},{"label":"B","text":"Reducing strength \\(\\text{Ag} > \\text{Ni} > \\text{Fe}\\); the cell with \\(\\text{Ag}(s)\\) as the anode and \\(\\text{Fe}^{2+}/\\text{Fe}\\) as the cathode gives \\(E^{\\circ}_{\\text{cell}} = +1.24\\ \\text{V}\\)."},{"label":"C","text":"Reducing strength \\(\\text{Fe} > \\text{Ni} > \\text{Ag}\\); the cell with \\(\\text{Ni}(s)\\) as the anode and \\(\\text{Ag}^{+}/\\text{Ag}\\) as the cathode gives \\(E^{\\circ}_{\\text{cell}} = +1.05\\ \\text{V}\\)."},{"label":"D","text":"Reducing strength \\(\\text{Fe} > \\text{Ni} > \\text{Ag}\\); the cell with \\(\\text{Fe}(s)\\) as the anode and \\(\\text{Ag}^{+}/\\text{Ag}\\) as the cathode gives \\(E^{\\circ}_{\\text{cell}} = +1.24\\ \\text{V}\\)."}]$op88$::jsonb,
    'D',
    $ex88$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is D because the reducing-strength ranking and the galvanic pairing must both be derived from the same principle: a more negative standard reduction potential means the reverse (oxidation) process is more favorable, so the metal is a stronger reducing agent. Ordering the couples by \(E^{\circ}_{\text{red}}\), \(\text{Fe}^{2+}/\text{Fe}\) is most negative (\(-0.44\ \text{V}\)), \(\text{Ni}^{2+}/\text{Ni}\) is intermediate (\(-0.25\ \text{V}\)), and \(\text{Ag}^{+}/\text{Ag}\) is most positive (\(+0.80\ \text{V}\)); therefore reducing strength of the metals runs \(\text{Fe} > \text{Ni} > \text{Ag}\). To deliver a positive cell potential while oxidizing the strongest reducing agent, iron must be the anode (oxidation: \(\text{Fe} \rightarrow \text{Fe}^{2+} + 2e^-\)), and the couple with the most positive reduction potential, \(\text{Ag}^{+}/\text{Ag}\), must be the cathode (reduction: \(\text{Ag}^{+} + e^- \rightarrow \text{Ag}\)). Applying \(E^{\circ}_{\text{cell}} = E^{\circ}_{\text{red,cathode}} - E^{\circ}_{\text{red,anode}} = (+0.80\ \text{V}) - (-0.44\ \text{V}) = +1.24\ \text{V}\), which is positive, confirming a spontaneous galvanic cell (\(\Delta G^{\circ} = -nFE^{\circ}_{\text{cell}} < 0\)). Note that \(E^{\circ}\) is intensive: even though the balanced reaction needs two \(\text{Ag}^{+}\) per \(\text{Fe}\), the silver potential is not multiplied by 2. (Choice A) keeps the correct ranking and the correct Fe-anode/Ag-cathode assignment but computes the potential by adding the two reduction potentials' magnitudes incorrectly (or subtracting \(0.44\) from \(0.80\)), yielding \(+0.36\ \text{V}\); the correct subtraction \((+0.80) - (-0.44)\) adds the two magnitudes to give \(+1.24\ \text{V}\). (Choice B) reverses the relationship between reduction potential and reducing strength, ranking \(\text{Ag} > \text{Ni} > \text{Fe}\) by treating the most positive \(E^{\circ}_{\text{red}}\) as the strongest reducer; it then makes silver the anode and iron the cathode, which gives \(E^{\circ}_{\text{cell}} = E^{\circ}_{\text{red,cathode}} - E^{\circ}_{\text{red,anode}} = (-0.44) - (+0.80) = -1.24\ \text{V}\), a negative (nonspontaneous) value that has merely been relabeled as \(+1.24\ \text{V}\). (Choice C) has the correct ranking but assigns nickel rather than iron as the anode; although the Ni/Ag cell is spontaneous, with \(E^{\circ}_{\text{cell}} = (+0.80) - (-0.25) = +1.05\ \text{V}\), it fails the requirement to oxidize the strongest reducing agent (iron), so it is not the specified cell. Skill 2$ex88$,
    'hard', '4C', $cc88$Electrochemistry (GC)$cc88$, 'general-chemistry', 2, 160
  ) RETURNING id
)
